<?php
require_once '../config/database.php';require_once '../includes/auth.php';require_role('teacher');$page_title='Статистика';
$q=$pdo->prepare('SELECT id FROM teachers WHERE user_id=?');$q->execute([$_SESSION['user']['id']]);$tid=(int)$q->fetchColumn();
$q=$pdo->prepare("SELECT st.id,CONCAT(st.surname,' ',st.name) student_name,g.name group_name,SUM(a.status='PRESENT') present_count,SUM(a.status='ABSENT') absent_count,SUM(a.status='LATE') late_count,COUNT(a.id) total,(SELECT ROUND(AVG(gr.grade),2) FROM grades gr WHERE gr.student_id=st.id AND gr.teacher_id=?) avg_grade FROM students st JOIN groups g ON g.id=st.group_id JOIN lessons l ON l.group_id=st.group_id AND l.teacher_id=? LEFT JOIN attendance a ON a.student_id=st.id AND a.lesson_id=l.id GROUP BY st.id ORDER BY g.name,st.surname");$q->execute([$tid,$tid]);$rows=$q->fetchAll();
$q=$pdo->prepare('SELECT s.name,ROUND(AVG(gr.grade),2) avg_grade,COUNT(gr.id) cnt FROM grades gr JOIN subjects s ON s.id=gr.subject_id WHERE gr.teacher_id=? GROUP BY s.id ORDER BY s.name');$q->execute([$tid]);$subjects=$q->fetchAll();include '../includes/header.php';?>
<div class="statistics-grid"><div class="panel statistics-panel"><h2>Статистика моих групп</h2><div class="table-wrap"><table><tr><th>Студент</th><th>Группа</th><th>Посещено</th><th>Пропущено</th><th>Опозданий</th><th>Посещаемость</th><th>Средний балл</th></tr><?php foreach($rows as $r):$pct=$r['total']?round(($r['present_count']+$r['late_count'])/$r['total']*100):0;?><tr><td><?=htmlspecialchars($r['student_name'])?></td><td><?=htmlspecialchars($r['group_name'])?></td><td><?=$r['present_count']?></td><td><?=$r['absent_count']?></td><td><?=$r['late_count']?></td><td><b><?=$pct?>%</b><div class="progress"><i style="width:<?=$pct?>%"></i></div></td><td><b><?=$r['avg_grade']?:'—'?></b></td></tr><?php endforeach;?></table></div></div><div class="panel statistics-panel"><h2>Средний балл по предметам</h2><?php if($subjects):?><div class="table-wrap"><table><tr><th>Предмет</th><th>Оценок</th><th>Средний</th></tr><?php foreach($subjects as $r):?><tr><td><?=htmlspecialchars($r['name'])?></td><td><?=$r['cnt']?></td><td><b><?=$r['avg_grade']?></b></td></tr><?php endforeach;?></table></div><?php else:?><div class="empty-state">Оценок пока нет.</div><?php endif;?></div></div>
<?php include '../includes/footer.php';?>
